from pathlib import Path
import json
import shutil
import sys

MNT_DATA = Path('/mnt/data')
OUTPUT_ROOT = MNT_DATA / 'output'


def _copy_if_needed(source_name: str) -> Path:
    source = Path(source_name)
    target = MNT_DATA / source.name
    if source.resolve() != target.resolve():
        shutil.copy2(source, target)
    return target


def initialize_environment() -> dict:
    MNT_DATA.mkdir(parents=True, exist_ok=True)
    OUTPUT_ROOT.mkdir(parents=True, exist_ok=True)
    if str(MNT_DATA) not in sys.path:
        sys.path.insert(0, str(MNT_DATA))
    return {
        'status': 'ready',
        'working_directory': str(MNT_DATA),
        'output_root': str(OUTPUT_ROOT),
        'message': 'Prześlij jeden plik PDF do analizy; backend uruchomi się automatycznie po otrzymaniu pliku.'
    }


def select_pdf(explicit_pdf: str | None = None) -> Path:
    if explicit_pdf:
        pdf = Path(explicit_pdf)
        if not pdf.is_absolute():
            pdf = MNT_DATA / pdf
        if pdf.is_file() and pdf.suffix.lower() == '.pdf':
            return pdf
        raise FileNotFoundError(f'Brak pliku PDF: {pdf}')
    pdfs = sorted(MNT_DATA.glob('*.pdf'), key=lambda p: p.stat().st_mtime, reverse=True)
    if not pdfs:
        raise FileNotFoundError('Brak pliku PDF w /mnt/data. Prześlij jeden plik PDF do analizy.')
    return pdfs[0]


def run_after_pdf_received(pdf_path: str | None = None, backend_module: str | None = None) -> dict:
    initialize_environment()
    pdf = select_pdf(pdf_path)
    from pdf_backend_launcher import run_pdf_analysis
    output_dir = OUTPUT_ROOT / pdf.stem
    return run_pdf_analysis(str(pdf), str(output_dir), backend_module)


if __name__ == '__main__':
    print(json.dumps(initialize_environment(), ensure_ascii=False, indent=2))
